mapper.select:
SELECT (
SELECT count(*) FROM PRD_SALE_PARAM LEFT JOIN FIN_PRODUCT ON PRD_SALE_PARAM.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
LEFT JOIN ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE, SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R1S1}
LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
WHERE PRD_SALE_PARAM.FIRST_SALE_VDATE <= #{quaryDate} AND PRD_SALE_PARAM.FIRST_SALE_MDATE >= #{quaryDate} AND FIN_PRODUCT.FINPROD_TYPE2 = #{finType_F16} AND FIN_PRODUCT.P_FINPROD_ID IS NULL
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R1S1} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = PRD_SALE_PARAM.FINPROD_ID ) ) as R1S1, (
SELECT count(*) FROM FIN_PRODUCT INNER JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
LEFT JOIN ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE, SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R1S2}
LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE( FIN_PRODUCT.VDATE <= #{quaryDate}+REMINDER_SET.DAYS OR FIN_PRODUCT.VDATE <= #{quaryDate} ) AND FIN_PRODUCT.FINPROD_TYPE2 = #{finType_F16} AND FIN_PRODUCT.P_FINPROD_ID IS NULL AND FIN_PRODUCT_ADD.ISSUE_STATUS = '03'
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND NOT EXISTS ( SELECT 1 FROM TRD_PRODUCT_DEAL WHERE FIN_PRODUCT.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND TRD_PRODUCT_DEAL.PS = #{ps_C1} AND TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag} AND TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatus_01})
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R1S2} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID ) )as R1S2, (
SELECT count(*) FROM FIN_CASH_PLAN LEFT JOIN FIN_CASH_INFO ON FIN_CASH_PLAN.CASH_ID = FIN_CASH_INFO.CASH_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN FIN_PRODUCT ON FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R1S3}
LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE( FIN_CASH_PLAN.PAY_DATE <= #{quaryDate}+REMINDER_SET.DAYS OR FIN_CASH_PLAN.PAY_DATE <= #{quaryDate} ) AND FIN_CASH_PLAN.CASH_TYPE = #{cashType_01} AND FIN_PRODUCT.PROFIT_TYPE in(#{profitType_02},#{profitType_03}) AND FIN_PRODUCT.FINPROD_TYPE2 = #{finType_F16} AND FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1_02} AND FIN_PRODUCT_ADD.ISSUE_STATUS = #{issueStatus_01} AND FIN_PRODUCT.P_FINPROD_ID IS NULL AND FIN_PRODUCT.Mdate > #{quaryDate}
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND NOT EXISTS ( SELECT 1 FROM TRD_PRODUCT_DEAL WHERE FIN_CASH_PLAN.CASH_ID = TRD_PRODUCT_DEAL.CASH_ID AND FIN_CASH_PLAN.MDATE = TRD_PRODUCT_DEAL.MDATE AND (TRD_PRODUCT_DEAL.PS = #{ps_C7} OR TRD_PRODUCT_DEAL.PS = #{ps_C9}) AND TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag} AND TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatus_01} )
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R1S3} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = FIN_CASH_PLAN.FINPROD_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = FIN_CASH_PLAN.PAY_DATE ) ) as R1S3, ( SELECT COUNT(*) FROM ( SELECT #{R1S4} as remType, SUM(TPRD.PRIN_AMT) as AMT, FIN_PRODUCT.FINPROD_ID as finprodId, FIN_PRODUCT.FINPROD_NAME as finprodName, CONCAT(IFNULL(TPRD.MDATE ,''), '子周期到期') as reminder, TPRD.BRANCH as BRANCH, REMINDER_SET.MENU_ID as menuId, REMINDER_SET.URL as url, REMINDER_SET.LABLE as lable, REMINDER_SET.DEALF as dealF, REMINDER_SET.CLOSF as closF, REMINDER_SET.DAYS as days FROM TRD_PRODUCT_DEAL TPRD LEFT JOIN FIN_PRODUCT ON TPRD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN PA_FIN_PRODUCT ON TPRD.FINPROD_ID = PA_FIN_PRODUCT.FINPROD_ID
LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R1S4}
LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE TPRD.MDATE <= #{quaryDate}+REMINDER_SET.DAYS AND TPRD.MDATE >= #{quaryDate} AND TPRD.PS in (#{ps_C1},#{ps_C2}) AND TPRD.IS_CANCEL = #{noFlag} AND TPRD.TRADE_STATUS = #{tradeStatus_01} AND FIN_PRODUCT.FINPROD_TYPE2 = #{finType_F16} AND PA_FIN_PRODUCT.DEAL_MODE in (#{dispose_10},#{dispose_12})
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R1S4} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = TPRD.MDATE )
AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL TPD WHERE TPD.PS = #{ps_C4} AND TPD.FINPROD_ID = TPRD.FINPROD_ID AND TPD.BRANCH = TPRD.BRANCH AND TPD.IS_CANCEL = #{noFlag} AND TPD.TRADE_STATUS = #{tradeStatus_01} ) GROUP BY FIN_PRODUCT.FINPROD_ID , FIN_PRODUCT.FINPROD_NAME , TPRD.MDATE, TPRD.BRANCH, REMINDER_SET.MENU_ID, REMINDER_SET.URL, REMINDER_SET.LABLE , REMINDER_SET.DEALF , REMINDER_SET.CLOSF , REMINDER_SET.DAYS )RES
WHERE NOT EXISTS( SELECT RES1.* FROM( SELECT TRD_PRODUCT_DEAL.BRANCH as BRANCH, TRD_PRODUCT_DEAL.FINPROD_ID as FINPROD_ID, SUM(TRD_PRODUCT_DEAL.PRIN_AMT) as AMT FROM TRD_PRODUCT_DEAL LEFT JOIN PA_FIN_PRODUCT ON TRD_PRODUCT_DEAL.FINPROD_ID = PA_FIN_PRODUCT.FINPROD_ID WHERE TRD_PRODUCT_DEAL.PS = #{ps_C17} AND PA_FIN_PRODUCT.DEAL_MODE in (#{dispose_10},#{dispose_12}) AND TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag} AND TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatus_01} GROUP BY TRD_PRODUCT_DEAL.BRANCH,TRD_PRODUCT_DEAL.FINPROD_ID )RES1 WHERE RES.finprodId = RES1.FINPROD_ID AND RES.BRANCH = RES1.BRANCH AND RES.AMT <= RES1.AMT ) ) as R1S4, (
SELECT count(*) FROM FIN_PRODUCT
LEFT JOIN ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE, SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R1S5}
LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE ( FIN_PRODUCT.MDATE <= #{quaryDate}+REMINDER_SET.DAYS OR FIN_PRODUCT.MDATE <= #{quaryDate} ) AND FIN_PRODUCT.FINPROD_TYPE2 = #{finType_F16} AND FIN_PRODUCT.P_FINPROD_ID IS NULL
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND NOT EXISTS ( SELECT 1 FROM TRD_PRODUCT_DEAL WHERE FIN_PRODUCT.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND TRD_PRODUCT_DEAL.PS = #{ps_C5} AND TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag} AND TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatus_01})
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R1S5} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID ) )as R1S5, (
SELECT count(*) FROM ( SELECT #{R1S6} as remType, FIN_PRODUCT.FINPROD_MARKET_ID as finprodId, FIN_PRODUCT.FINPROD_ID as prodId, FIN_PRODUCT.FINPROD_NAME as finprodName, CONCAT('产品需进行:',IFNULL(MST_FEEINFO.FEE_NAME,''),'(', IFNULL(MST_FEEINFO.FEE_ID,'') ,')支付') as reminder, FIN_CASH_PLAN.PAY_DATE as mdate, MST_FEEINFO .FEE_ID as feeId, REMINDER_SET.MENU_ID as menuId, REMINDER_SET.URL as url, REMINDER_SET.LABLE as lable, REMINDER_SET.DEALF as dealF, REMINDER_SET.CLOSF as closF, REMINDER_SET.DAYS as days FROM FIN_CASH_INFO INNER JOIN FIN_CASH_PLAN ON FIN_CASH_PLAN.CASH_ID=FIN_CASH_INFO.CASH_ID INNER JOIN MST_FEEINFO ON FIN_CASH_INFO.FEE_ID=MST_FEEINFO.FEE_ID AND MST_FEEINFO.charge_type = #{chargeType_01} INNER JOIN BOK_POSITION_PRDFEE ON FIN_CASH_INFO.FINPROD_ID=BOK_POSITION_PRDFEE.FINPROD_ID AND FIN_CASH_INFO.BRANCH=BOK_POSITION_PRDFEE.BRANCH AND BOK_POSITION_PRDFEE.FEE_TYPE = FIN_CASH_INFO.CASH_TYPE_2 LEFT JOIN FIN_PRODUCT ON FIN_CASH_INFO.FINPROD_ID=FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID LEFT JOIN STL_FIN_PRODUCT_ACCT ON STL_FIN_PRODUCT_ACCT.FINPROD_ID=FIN_CASH_INFO.FINPROD_ID AND STL_FIN_PRODUCT_ACCT.CCY=FIN_CASH_INFO.CCY AND STL_FIN_PRODUCT_ACCT.ACCT_TYPE = 'B12' LEFT JOIN STL_FIN_PRODUCT_ACCT STL_FIN_PRODUCT_ACCT1 ON STL_FIN_PRODUCT_ACCT1.FINPROD_ID=FIN_CASH_INFO.FINPROD_ID AND STL_FIN_PRODUCT_ACCT1.CCY=FIN_CASH_INFO.CCY AND STL_FIN_PRODUCT_ACCT1.CASH_ID = FIN_CASH_INFO.CASH_ID LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R1S6} WHERE FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1_03} AND BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP > 0 AND FIN_CASH_PLAN.MDATE <= #{platDate} AND FIN_CASH_PLAN.PAY_DATE <= #{quaryDate} AND FIN_CASH_PLAN.CASH_TYPE = #{cashType_05} AND FIN_CASH_INFO.FINPROD_TYPE = #{finprodType_01} AND FIN_PRODUCT_ADD.ISSUE_STATUS = #{issueStatus_01} AND FIN_PRODUCT.FINPROD_TYPE2 = #{finType_F16} and not exists (select 1 from TRD_PRODUCT_DEAL where FIN_CASH_PLAN.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID and FIN_CASH_PLAN.MDATE = TRD_PRODUCT_DEAL.MDATE AND FIN_CASH_PLAN.BRANCH=TRD_PRODUCT_DEAL.BRANCH AND BOK_POSITION_PRDFEE.FEE_TYPE=TRD_PRODUCT_DEAL.FINPROD_TYPE2 and TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag} and TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatus_01}) AND BOK_POSITION_PRDFEE.CDATE = (SELECT max(B.CDATE) FROM BOK_POSITION_PRDFEE B WHERE B.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND B.BRANCH = BOK_POSITION_PRDFEE.BRANCH AND B.FEE_TYPE = BOK_POSITION_PRDFEE.FEE_TYPE AND B.CDATE < FIN_CASH_PLAN.MDATE)
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
) zz ) as R1S6 FROM DUAL

SELECT (
SELECT count(*) FROM FIN_PRODUCT T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2
LEFT JOIN ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE, SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R2S1}
AND T2.FINPROD_TYPE2 = #{finType_F18} AND T2.MDATE-5 <= #{quaryDate}+REMINDER_SET.DAYS AND T2.MDATE-5 >= #{quaryDate} AND T2.CASH_TYPE in
(#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
AND NOT EXISTS( select 1 from TRD_PRODUCT_DEAL T3
T2.VDATE = T3.VDATE AND T2.MDATE = T3.MDATE AND T2.PAY_DATE = T3.SETTLE_DATE AND T2.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{finType_F18} AND T3.IS_CANCEL = #{noFlag} AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{cashType_01},#{cashType_02},#{cashType_03})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R2S1} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T2.MDATE )
)as R2S1, (
SELECT count(*) FROM FIN_PRODUCT T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2
LEFT JOIN ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE, SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R2S2}
AND T2.FINPROD_TYPE2 = #{finType_F18} AND ADDDATE(T2.MDATE,-1) <= #{quaryDate}+REMINDER_SET.DAYS AND ADDDATE(T2.MDATE,-1) >= #{quaryDate} AND T2.CASH_TYPE in
(#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
AND NOT EXISTS( select 1 from TRD_PRODUCT_DEAL T3
T2.VDATE = T3.VDATE AND T2.MDATE = T3.MDATE AND T2.PAY_DATE = T3.SETTLE_DATE AND T2.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{finType_F18} AND T3.IS_CANCEL = #{noFlag} AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{cashType_01},#{cashType_02},#{cashType_03})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R2S2} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T2.MDATE )
)as R2S2, (
SELECT count(*) FROM FIN_PRODUCT T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2
LEFT JOIN ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE, SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R2S3}
AND T2.FINPROD_TYPE2 = #{finType_F18} AND ADDDATE(T2.MDATE,-3) <= #{quaryDate}+REMINDER_SET.DAYS AND ADDDATE(T2.MDATE,-3) >= #{quaryDate} AND T2.CASH_TYPE in
(#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
AND NOT EXISTS( select 1 from TRD_PRODUCT_DEAL T3
T2.VDATE = T3.VDATE AND T2.MDATE = T3.MDATE AND T2.PAY_DATE = T3.SETTLE_DATE AND T2.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{finType_F18} AND T3.IS_CANCEL = #{noFlag} AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{cashType_01},#{cashType_02},#{cashType_03})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R2S3} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T2.MDATE )
)as R2S3, (
SELECT count(*) FROM FIN_PRODUCT T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2
LEFT JOIN ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE, SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R2S4}
AND T2.FINPROD_TYPE2 = #{finType_F17} AND T2.MDATE-5 <= #{quaryDate}+REMINDER_SET.DAYS AND T2.MDATE-5 >= #{quaryDate} AND T2.CASH_TYPE in
(#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
AND NOT EXISTS( select 1 from TRD_PRODUCT_DEAL T3
T2.MDATE = T3.MDATE AND T2.PAY_DATE = T3.SETTLE_DATE AND T2.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{finType_F17} AND T3.IS_CANCEL = #{noFlag} AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{income},#{returnThis},#{maturity},#{ps_T22},#{ps_T23})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R2S4} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T2.MDATE )
)as R2S4, (
SELECT count(*) FROM FIN_PRODUCT T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2
LEFT JOIN ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE, SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R2S5}
AND T2.FINPROD_TYPE2 = #{finType_F17} AND ADDDATE(T2.MDATE,-1) <= #{quaryDate}+REMINDER_SET.DAYS AND ADDDATE(T2.MDATE,-1) >= #{quaryDate} AND T2.CASH_TYPE in
(#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
AND NOT EXISTS( select 1 from TRD_PRODUCT_DEAL T3
T2.MDATE = T3.MDATE AND T2.PAY_DATE = T3.SETTLE_DATE AND T2.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{finType_F17} AND T3.IS_CANCEL = #{noFlag} AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{income},#{returnThis},#{maturity},#{ps_T22},#{ps_T23})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R2S5} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T2.MDATE )
)as R2S5, (
SELECT count(*) FROM FIN_PRODUCT T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2
LEFT JOIN ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE, SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R2S6}
AND T2.FINPROD_TYPE2 = #{finType_F17} AND ADDDATE(T2.MDATE,-3) <= #{quaryDate}+REMINDER_SET.DAYS AND ADDDATE(T2.MDATE,-3) >= #{quaryDate} AND T2.CASH_TYPE in
(#{cashType_01},#{cashType_02},#{cashType_03},#{cashType_04})
AND NOT EXISTS( select 1 from TRD_PRODUCT_DEAL T3
T2.MDATE = T3.MDATE AND T2.PAY_DATE = T3.SETTLE_DATE AND T2.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{finType_F17} AND T3.IS_CANCEL = #{noFlag} AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{income},#{returnThis},#{maturity},#{ps_T22},#{ps_T23})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R2S6} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T2.MDATE )
)as R2S6 FROM DUAL

SELECT count(*) FROM ( SELECT T2.FINPROD_ID AS assetCode, T2.FINPROD_ABBR AS assetName FROM FIN_CASH_PLAN T1,FIN_PRODUCT T2
T1.FINPROD_ID=T2.FINPROD_ID AND T1.FINPROD_TYPE2=T2.FINPROD_TYPE2 AND T1.FINPROD_TYPE2=#{plannedAssets} AND T1.PAY_DATE_UNADJUST-CAST(#{configurationDays}) <= #{quaryDate} AND T1.PAY_DATE_UNADJUST >= #{quaryDate} AND T1.CASH_TYPE IN (#{midIncome},#{midReturn},#{dueRepayment}) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL T3
T1.VDATE = T3.VDATE AND T1.MDATE = T3.MDATE AND T1.PAY_DATE = T3.SETTLE_DATE AND T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{plannedAssets} AND T3.IS_CANCEL = #{no} AND T3.PS IN (#{returnThis},#{maturity},#{purchase})
)
) zz

SELECT
count(*)
FROM
FIN_EXERCISE_PLAN T1,FIN_PRODUCT T2

    T1.FINPROD_ID = T2.FINPROD_ID
    AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2
    AND T1.VDATE-CAST(#{configurationDays}) <= #{quaryDate}
    AND T1.EXERCISE_DATE >= #{quaryDate}
    AND T1.EXERCISE_STATUS = #{unauthorized}

SELECT (SELECT count(*) FROM (SELECT distinct '01' VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.WORKFLOW_ID, T1.B_TRADE_ID, T2.PORTFOLIO_ID FROM ( select * from (SELECT * FROM WFL_TRD_PRODUCT_DEAL UNION ALL SELECT W1.* FROM WFL_TRD_PRODUCT_DEAL W1 INNER JOIN WFL_TRD_PRODUCT_DEAL W2 ON W1.B_TRADE_ID = W2.TRADE_ID WHERE W1.PS = 'T24') zz ) T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID WHERE (T1.IS_CANCEL is null or T1.IS_CANCEL = #{noFlag}) and T1.TRADE_STATUS = '01') tpd LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = tpd.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = fp.FINPROD_ID LEFT JOIN SYS_ACTIVEREMINDER_SET T5 on 1 = 1 WHERE tpd.FINPROD_TYPE2 = #{fund} AND tpd.PS in ('T24', #{ps_T02}, #{ps_T11}) and fpt.type_6 = #{nonmonetaryFund} AND T5.REM_TYPE = #{R3S1}
AND date_add(tpd.TRADE_DATE, interval -CAST(T5.DAYS as SIGNED INTEGER) day) <= str_to_date(#{quaryDate}, '%Y-%m-%d %H:%i:%s') AND tpd.TRADE_DATE >= #{quaryDate} AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S1} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = fp.FINPROD_ID) ) as R3S1, (SELECT count(*) FROM (SELECT distinct '01' VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.WORKFLOW_ID, T1.B_TRADE_ID, T2.PORTFOLIO_ID FROM (select * from (SELECT * FROM WFL_TRD_PRODUCT_DEAL UNION ALL SELECT W1.* FROM WFL_TRD_PRODUCT_DEAL W1 INNER JOIN WFL_TRD_PRODUCT_DEAL W2 ON W1.B_TRADE_ID = W2.TRADE_ID WHERE W1.PS IN ('T24')) zz) T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID WHERE (T1.IS_CANCEL is null or T1.IS_CANCEL = #{noFlag}) and T1.TRADE_STATUS = '01') tpd LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = tpd.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = fp.FINPROD_ID LEFT JOIN SYS_ACTIVEREMINDER_SET T5 on 1 = 1 WHERE tpd.FINPROD_TYPE2 = #{fund} AND tpd.PS in ('T24', #{ps_T02}, #{ps_T11}) and fpt.type_6 = #{monetaryFund} AND T5.REM_TYPE = #{R3S2} AND date_add(tpd.TRADE_DATE, interval -CAST(T5.DAYS as SIGNED INTEGER) day) <= str_to_date(#{quaryDate}, '%Y-%m-%d %H:%i:%s') AND tpd.TRADE_DATE >= #{quaryDate} AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S2} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = fp.FINPROD_ID) ) as R3S2,
( SELECT count(*) FROM ( SELECT distinct 'R3S3' as remType, fp.FINPROD_ID as assetId, fp.Finprod_Market_Id as assetCode, fp.FINPROD_NAME as assetName, (case when tpd.PS = 'T24' then '回款确认' when tpd.PS = 'T02' then '卖出' when tpd.PS = 'T11' then '现金分红' end) as reminder, T5.MENU_ID as menuId, T5.URL as url, T5.LABLE as lable, T5.DEALF as dealF, T5.CLOSF as closF, T5.DAYS as days FROM (SELECT distinct '01' VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.WORKFLOW_ID, T1.B_TRADE_ID, T2.PORTFOLIO_ID FROM (select * from (SELECT * FROM WFL_TRD_PRODUCT_DEAL UNION ALL SELECT W1.* FROM WFL_TRD_PRODUCT_DEAL W1 INNER JOIN WFL_TRD_PRODUCT_DEAL W2 ON W1.B_TRADE_ID = W2.TRADE_ID WHERE W1.PS = 'T24') zz) T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID WHERE (T1.IS_CANCEL is null or T1.IS_CANCEL = #{noFlag}) and T1.TRADE_STATUS = #{tradeStatus_01}) tpd LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = tpd.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN SYS_ACTIVEREMINDER_SET T5 on 1 = 1 WHERE tpd.FINPROD_TYPE2 = #{finType_F17} AND tpd.PS in ('T24', #{ps_T11}) AND fp.PROFIT_TYPE=#{profitType_01} AND T5.REM_TYPE = #{R3S3} AND date_add(tpd.TRADE_DATE, interval -CAST(T5.DAYS as SIGNED INTEGER) day) <= str_to_date(#{quaryDate}, '%Y-%m-%d %H:%i:%s') AND tpd.TRADE_DATE >= #{quaryDate} AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S3} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = fp.FINPROD_ID) ) zz ) as R3S3,
(SELECT COUNT(*) FROM FIN_PRODUCT T1, FIN_CASH_INFO T2, FIN_CASH_PAY_RULE T3, SYS_ACTIVEREMINDER_SET T5 WHERE T1.FINPROD_ID = T2.FINPROD_ID AND T2.CASH_ID = T3.CASH_ID AND T1.FINPROD_TYPE2 = #{fund} AND T1.PROFIT_TYPE = #{currency} AND T3.PAY_CYCLE = #{paycycle} AND concat(SUBSTRING(DATE_FORMAT(#{quaryDate},'%Y-%m-%d'), 0, 8), case WHEN t3.day_value < 10 THEN CONCAT_WS( '','0',t3.day_value ) ELSE t3.day_value END = DATE_FORMAT(#{quaryDate},'%Y-%m-%d')) AND T3.EFF_DATE <= #{quaryDate} AND T5.REM_TYPE = #{R3S4}
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S4} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T1.FINPROD_ID ) AND NOT EXISTS (select 1 from TRD_PRODUCT_DEAL T4 where T1.FINPROD_ID = T4.FINPROD_ID AND T4.PS IN (#{ps_T11},#{ps_T12}) AND T4.IS_CANCEL = #{noFlag}) )as R3S4, ( SELECT count(*) FROM FIN_CASH_PLAN T1,FIN_PRODUCT T2
LEFT JOIN ( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE, SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R3S10}
T1.FINPROD_ID=T2.FINPROD_ID AND T1.FINPROD_TYPE2=T2.FINPROD_TYPE2 AND T1.FINPROD_TYPE2=#{finType_F17} AND ( T1.MDATE <= #{quaryDate}+REMINDER_SET.DAYS or T1.MDATE <= #{quaryDate} ) AND T1.CASH_TYPE IN (#{cashType_01},#{cashType_02},#{cashType_03})
AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL T3
T1.MDATE = T3.MDATE
AND T1.FINPROD_ID = T3.FINPROD_ID
AND T3.IS_CANCEL = 'Y' AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{returnThis},#{ps_T22},#{ps_T23})
)
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S10} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T2.FINPROD_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = T1.MDATE )
and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.IS_CANCEL = 'N' and T2.MDATE = TPDA.MDATE AND TPDA.FINPROD_ID = T2.FINPROD_ID)
)as R3S10,
( SELECT count(*) FROM (SELECT distinct '01' VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.TRADE_DATE, T1.SETTLE_DATE, T1.WORKFLOW_ID, T1.B_TRADE_ID, T2.PORTFOLIO_ID FROM (select * from (SELECT * FROM WFL_TRD_PRODUCT_DEAL UNION ALL SELECT W1.* FROM WFL_TRD_PRODUCT_DEAL W1 INNER JOIN WFL_TRD_PRODUCT_DEAL W2 ON W1.B_TRADE_ID = W2.TRADE_ID WHERE W1.PS = 'T24') zz ) T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID WHERE (T1.IS_CANCEL is null or T1.IS_CANCEL = #{noFlag}) and T1.TRADE_STATUS = #{tradeStatus_01}) tpd LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = tpd.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN SYS_ACTIVEREMINDER_SET T5 on 1 = 1 WHERE tpd.FINPROD_TYPE2 = #{finType_F17} AND tpd.PS in ('T24', #{ps_T02}, #{ps_T11}) AND fp.PROFIT_TYPE=#{profitType_03} AND T5.REM_TYPE = #{R3S12} AND date_add(tpd.TRADE_DATE, interval -CAST(T5.DAYS as SIGNED INTEGER) day) <= str_to_date(#{quaryDate}, '%Y-%m-%d %H:%i:%s') AND tpd.TRADE_DATE >= #{quaryDate} AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S12} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = fp.FINPROD_ID) )as R3S12 FROM DUAL

SELECT count(*) FROM ( SELECT T2.FINPROD_ID AS assetCode, T2.FINPROD_ABBR AS assetName FROM FIN_CASH_PLAN T1,FIN_PRODUCT T2
T1.FINPROD_ID=T2.FINPROD_ID AND T1.FINPROD_TYPE2=T2.FINPROD_TYPE2 AND T1.FINPROD_TYPE2=#{bond} AND T1.PAY_DATE_UNADJUST-CAST(#{configurationDays} AS SIGNED INTEGER) <= #{quaryDate} AND T1.PAY_DATE_UNADJUST >= #{quaryDate} AND T1.CASH_TYPE IN (#{midIncome},#{midReturn},#{dueRepayment}) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL T3
T1.VDATE = T3.VDATE AND T1.MDATE = T3.MDATE AND T1.PAY_DATE = T3.SETTLE_DATE AND T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{bond} AND T3.IS_CANCEL = #{no} AND T3.PS IN (#{returnThis},#{maturity},#{purchase})
)
) zz

SELECT count(*) FROM ( SELECT T2.FINPROD_ID AS assetCode, T2.FINPROD_ABBR AS assetName FROM FIN_CASH_PLAN T1,FIN_PRODUCT T2
T1.FINPROD_ID=T2.FINPROD_ID AND T1.FINPROD_TYPE2=T2.FINPROD_TYPE2 AND T1.FINPROD_TYPE2=#{projectAssets} AND T1.PAY_DATE_UNADJUST-CAST(#{configurationDays} AS SIGNED INTEGER) <= #{quaryDate} AND T1.PAY_DATE_UNADJUST >= #{quaryDate} AND T1.CASH_TYPE IN (#{midIncome},#{midReturn},#{dueRepayment}) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL T3
T1.VDATE = T3.VDATE AND T1.MDATE = T3.MDATE AND T1.PAY_DATE = T3.SETTLE_DATE AND T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{projectAssets} AND T3.IS_CANCEL = #{no} AND T3.PS IN (#{returnThis},#{maturity},#{purchase})
)
) zz

SELECT (
SELECT count(*) FROM FIN_EXERCISE_PLAN T1,FIN_PRODUCT T2,( SELECT SYS_ACTIVEREMINDER_SET.REM_TYPE,SYS_ACTIVEREMINDER_SET.DAYS CONFIGURATIONDAYS, #{quaryDate}+SYS_ACTIVEREMINDER_SET.DAYS as DAYS FROM SYS_ACTIVEREMINDER_SET ) T3 where T1.FINPROD_ID = T2.FINPROD_ID AND T3.REM_TYPE='R4S1' AND T1.FINPROD_TYPE2 = T2.FINPROD_TYPE2
AND T1.EXERCISE_DATE-T3.CONFIGURATIONDAYS <= #{quaryDate}
AND T1.MDATE >= #{quaryDate}
AND T1.EXERCISE_STATUS = #{unauthorized}
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R4S1} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T2.FINPROD_ID ) ) as R4S1, (SELECT count(*) FROM INTERF_PAYHSRCSECINFO WIND LEFT JOIN FIN_PRODUCT FIN ON WIND.MARKET = FIN.TRADE_MARKET AND DATE_FORMAT(WIND.VDATE,'%Y-%m-%d') = DATE_FORMAT(FIN.VDATE,'%Y-%m-%d') AND DATE_FORMAT(WIND.MDATE,'%Y-%m-%d') = DATE_FORMAT(FIN.MDATE,'%Y-%m-%d') AND WIND.ISSUEAMT = FIN.ISSUE_AMT AND WIND.ISSUERSHORT = FIN.ISSUER AND trim(WIND.COUPONSPECIES) = FIN.COUPON_SPECIES LEFT JOIN FIN_TRADE_PRODUCT T ON T.FINPROD_ID = FIN.FINPROD_ID AND WIND.INTERESTRATE = T.INT_TYPE AND WIND.PAPERIR = T.INT_RATE LEFT JOIN Fin_Product_Add A ON A.FINPROD_ID = FIN.FINPROD_ID LEFT JOIN (SELECT SYS_ACTIVEREMINDER_SET.DAYS, SYS_ACTIVEREMINDER_SET.URL, SYS_ACTIVEREMINDER_SET.LABLE, SYS_ACTIVEREMINDER_SET.DEALF, SYS_ACTIVEREMINDER_SET.CLOSF FROM SYS_ACTIVEREMINDER_SET WHERE SYS_ACTIVEREMINDER_SET.REM_TYPE = #{R4S2}) REMINDER_SET ON 1 = 1 WHERE WIND.SECCODE != FIN.FINPROD_MARKET_ID AND date_add(WIND.CREATE_TIME, interval -CAST(REMINDER_SET.DAYS as SIGNED INTEGER) day) <= str_to_date(#{quaryDate}, '%Y-%m-%d %H:%i:%s')
AND WIND.CREATE_TIME >= #{quaryDate} AND FIN.FINPROD_TYPE2 = 'F01' AND A.IS_AUTO_UPDATE='Y' AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R4S2} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = FIN.FINPROD_ID) ) as R4S2 FROM DUAL

select SUM(zz.R5S1) R5S1,SUM(zz.R5S2) R5S2 from(
SELECT count(
(case
when A.SUP_STAT = #{R5S1,jdbcType=VARCHAR}
then A.SUP_STAT
end)
) R5S1,
count(
(case
when A.SUP_STAT = #{R5S2,jdbcType=VARCHAR}
then A.SUP_STAT
when A.SUP_STAT = #{R5S3,jdbcType=VARCHAR}
then A.SUP_STAT
end)
) R5S2
