union all
SELECT count(
(case
when A.SUP_STAT = #{R5S1,jdbcType=VARCHAR}
then A.SUP_STAT
end)
) R5S1,
count(
(case
when A.SUP_STAT = #{R5S2,jdbcType=VARCHAR}
then A.SUP_STAT
when A.SUP_STAT = #{R5S3,jdbcType=VARCHAR}
then A.SUP_STAT
end)
) R5S2
FROM RSK_ISUP_TRIAL A
LEFT JOIN(
